// Tests the per-class `asciiPlistAnnotation` overrides against the output of
// Ruby's `ascii_plist_annotation` (xcodeproj 1.27.0).
//
// The expectations in test/fixtures/annotations/*.annotations.json are
// generated by test/fixtures/annotations/generate.rb: `{uuid => annotation}`
// for every object of the sibling `*.xcodeproj` fixture. The Flutter
// fixtures come straight from `flutter create` (iOS and macOS, with and
// without Swift Package Manager integration); `edge` is built with the Ruby
// gem to cover shapes the templates lack (unnamed shell script phases,
// remote packages, SPM build files, nested file paths).

import 'dart:convert';
import 'dart:io';

import 'package:dart_xcodeproj/src/object/abstract_object.dart';
import 'package:dart_xcodeproj/src/pbx/pbx_build_file.dart';
import 'package:dart_xcodeproj/src/pbx/pbx_build_phase.dart';
import 'package:dart_xcodeproj/src/pbx/pbx_container_item_proxy.dart';
import 'package:dart_xcodeproj/src/pbx/pbx_target_dependency.dart';
import 'package:dart_xcodeproj/src/pbx/swift_package_references.dart';
import 'package:dart_xcodeproj/src/pbx/xc_swift_package_product_dependency.dart';
import 'package:dart_xcodeproj/src/project/xcode_project.dart';
import 'package:test/test.dart';

const _fixtureDir = 'test/fixtures/annotations';
const _fixtures = ['ios', 'macos', 'ios_spm', 'macos_spm', 'edge'];

/// `{uuid => annotation}` as generated by Ruby; `null` means no annotation.
Map<String, String?> _expected(String name) {
  final raw =
      jsonDecode(File('$_fixtureDir/$name.annotations.json').readAsStringSync())
          as Map<String, dynamic>;
  return raw.map((k, v) => MapEntry(k, v as String?));
}

bool _isBuildPhase(AbstractObject o) => o is AbstractBuildPhase;

void main() {
  for (final name in _fixtures) {
    group('asciiPlistAnnotation matches Ruby on $name fixture', () {
      late XcodeProject project;
      late Map<String, String?> expected;

      setUpAll(() async {
        project = await XcodeProject.open('$_fixtureDir/$name.xcodeproj');
        expected = _expected(name);
      });

      void checkAll(String label, bool Function(AbstractObject) select) {
        test(label, () {
          final objects = project.objectsByUuid.values.where(select).toList();
          for (final obj in objects) {
            expect(
              obj.asciiPlistAnnotation,
              equals(expected[obj.uuid]),
              reason: '${obj.isa} ${obj.uuid}',
            );
          }
        });
      }

      checkAll('every object', (_) => true);
      checkAll('PBXContainerItemProxy', (o) => o is PBXContainerItemProxy);
      checkAll('PBXTargetDependency', (o) => o is PBXTargetDependency);
      checkAll('PBXBuildFile', (o) => o is PBXBuildFile);
      checkAll('build phases', _isBuildPhase);
      checkAll(
        'XCLocalSwiftPackageReference',
        (o) => o is XCLocalSwiftPackageReference,
      );
      checkAll(
        'XCRemoteSwiftPackageReference',
        (o) => o is XCRemoteSwiftPackageReference,
      );
      checkAll(
        'XCSwiftPackageProductDependency',
        (o) => o is XCSwiftPackageProductDependency,
      );
    });
  }

  group('expectations are not vacuous', () {
    test(
      'Flutter fixtures cover proxies, dependencies and shell phases',
      () async {
        final project = await XcodeProject.open('$_fixtureDir/ios.xcodeproj');
        final all = project.objectsByUuid.values;
        expect(all.whereType<PBXContainerItemProxy>(), isNotEmpty);
        expect(all.whereType<PBXTargetDependency>(), isNotEmpty);
        expect(all.whereType<PBXShellScriptBuildPhase>(), isNotEmpty);
        expect(all.whereType<PBXBuildFile>(), isNotEmpty);
      },
    );

    test(
      'SPM fixtures contain a productRef build file with no fileRef',
      () async {
        final project = await XcodeProject.open(
          '$_fixtureDir/ios_spm.xcodeproj',
        );
        final spmFiles = project.objectsByUuid.values
            .whereType<PBXBuildFile>()
            .where((f) => f.productRef != null && f.fileRef == null)
            .toList();
        expect(spmFiles, isNotEmpty);
        expect(
          spmFiles.single.asciiPlistAnnotation,
          equals(' FlutterGeneratedPluginSwiftPackage in Frameworks '),
        );
        expect(
          project.objectsByUuid.values
              .whereType<XCLocalSwiftPackageReference>(),
          isNotEmpty,
        );
      },
    );

    test('edge fixture has an unnamed shell script phase', () async {
      final project = await XcodeProject.open('$_fixtureDir/edge.xcodeproj');
      final unnamed = project.objectsByUuid.values
          .whereType<PBXShellScriptBuildPhase>()
          .where((p) => p.name == null)
          .toList();
      expect(unnamed, hasLength(1));
      expect(unnamed.single.asciiPlistAnnotation, equals(' ShellScript '));
    });
  });

  // The saved pbxproj prints the annotation each object reports, exactly:
  // every object header carries its Ruby annotation (none for the main group).
  for (final name in _fixtures) {
    test(
      'saved project annotates every object header like Ruby ($name)',
      () async {
        final dir = Directory.systemTemp.createTempSync('ascii_plist_anno_');
        addTearDown(() => dir.deleteSync(recursive: true));
        final bundle = Directory('${dir.path}/$name.xcodeproj')..createSync();
        File(
          '$_fixtureDir/$name.xcodeproj/project.pbxproj',
        ).copySync('${bundle.path}/project.pbxproj');

        final project = await XcodeProject.open(bundle.path);
        await project.save();
        final output = File(
          '${bundle.path}/project.pbxproj',
        ).readAsStringSync();

        final expected = _expected(name);
        for (final uuid in project.objectsByUuid.keys) {
          final annotation = expected[uuid];
          final header = annotation == null
              ? RegExp('^\t\t$uuid = ', multiLine: true)
              : RegExp(
                  '^\t\t$uuid /\\*${RegExp.escape(annotation)}\\*/ = ',
                  multiLine: true,
                );
          expect(output, _contains(header), reason: uuid);
        }
      },
    );
  }
}

/// A matcher for "the text contains a match of [pattern]".
Matcher _contains(RegExp pattern) => predicate<String>(
  pattern.hasMatch,
  'contains a match of ${pattern.pattern}',
);
